qValueExpression.qExpr:
=if('$(vDimZeit)' = 'Monat', only({<[_today_month]={1}>} Monat),
	if('$(vDimZeit)' = 'Woche', only({<[_today_week]={1}>} Woche),
    	if('$(vDimZeit)' = 'Jahr', only({<[_today_year]={1}>} Jahr),
        	if('$(vDimZeit)' = 'Quartal', only({<[_today_quarter]={1}>} Quarter),
            	if('$(vDimZeit)' = 'Tag', only({<[_today_day]={1}>} today()),
 )))))

